CREATE TABLE ai_conversation(id BIGINT NOT NULL,user_id BIGINT NOT NULL,title VARCHAR(200) NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'ACTIVE',created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_ai_conversation_user_time(user_id,updated_at));
CREATE TABLE ai_message(id BIGINT NOT NULL,conversation_id BIGINT NOT NULL,role VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,content MEDIUMTEXT NOT NULL,refused BOOLEAN NOT NULL DEFAULT FALSE,model_name VARCHAR(128) NULL,prompt_tokens INT UNSIGNED NULL,completion_tokens INT UNSIGNED NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_ai_message_conversation_time(conversation_id,created_at),CONSTRAINT fk_ai_message_conversation FOREIGN KEY(conversation_id) REFERENCES ai_conversation(id) ON DELETE CASCADE);
CREATE TABLE ai_citation(message_id BIGINT NOT NULL,sequence_no INT UNSIGNED NOT NULL,source_type VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,title VARCHAR(500) NOT NULL,excerpt TEXT NOT NULL,url VARCHAR(512) NULL,PRIMARY KEY(message_id,sequence_no),CONSTRAINT fk_ai_citation_message FOREIGN KEY(message_id) REFERENCES ai_message(id) ON DELETE CASCADE);
CREATE TABLE ai_tool_call(id BIGINT NOT NULL,message_id BIGINT NOT NULL,tool_name VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,arguments_json JSON NOT NULL,result_digest CHAR(64) NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_ai_tool_message(message_id));
